{-| @Backend.Runtime.Kernel.Http — a request head's header lines read in one
    pass, as `Std.Http.Message` reads them. -}
module Pudu.Backend.Runtime.Kernel.Http (httpKernelParts) where

import Data.Text (Text)

{-| Each part: its name, the parts it needs, and its lines. -}
httpKernelParts :: [(Text, [Text], [Text])]
httpKernelParts =
  [ ("http_header_pairs", ["array", "text", "text_view", "text_trim", "memory_failure"],
      [ "/* A header name: at least one letter, digit or token punctuation mark. */"
      , "static int pudu_http_token(const unsigned char *bytes, size_t length) {"
      , "  static const char punctuation[] = \"!#$%&'*+-.^_`|~\";"
      , "  if (length == 0) return 0;"
      , "  for (size_t i = 0; i < length; ++i) {"
      , "    unsigned char c = bytes[i];"
      , "    if ((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9')) continue;"
      , "    if (c == 0 || memchr(punctuation, c, sizeof punctuation - 1) == NULL) return 0;"
      , "  }"
      , "  return 1;"
      , "}"
      , "/* The lines after the request line, split as the head's own line breaks"
      , "   split it. Each line is checked and, when `pairs` is given, written as a"
      , "   name and its trimmed value; the answer is how many lines there were, or"
      , "   -1 for a line the reader does not take whole. */"
      , "static long pudu_http_header_lines(pudu_text head, pudu_box *(*pair)(pudu_text, pudu_text), pudu_items *pairs) {"
      , "  const unsigned char *bytes = head.bytes;"
      , "  size_t length = head.length, width = 1, at = 0, end;"
      , "  long count = 0;"
      , "  int first = 1;"
      , "  for (size_t i = 0; i + 1 < length; ++i) if (bytes[i] == '\\r' && bytes[i + 1] == '\\n') { width = 2; break; }"
      , "  while (at <= length) {"
      , "    size_t colon = 0;"
      , "    int found = 0;"
      , "    end = at;"
      , "    while (end < length && !(bytes[end] == (width == 2 ? '\\r' : '\\n') && (width == 1 || (end + 1 < length && bytes[end + 1] == '\\n')))) ++end;"
      , "    if (first) { first = 0; }"
      , "    else if (end > at) {"
      , "      if (bytes[at] == ' ' || bytes[at] == '\\t') return -1;"
      , "      for (size_t i = at; i < end; ++i) {"
      , "        if (bytes[i] == '\\r' || bytes[i] == '\\n') return -1;"
      , "        if (!found && bytes[i] == ':') { colon = i; found = 1; }"
      , "      }"
      , "      if (!found || !pudu_http_token(bytes + at, colon - at)) return -1;"
      , "      if (pairs != NULL) {"
      , "        pudu_text name = pudu_text_view(head, at, colon);"
      , "        pudu_text rest = {bytes + colon + 1, end - colon - 1, head.owner};"
      , "        pudu_text value = pudu_text_trim(rest);"
      , "        pairs->cells[count].box = pair(name, value);"
      , "        pudu_text_release(name);"
      , "        pudu_text_release(value);"
      , "        pairs->length = (size_t)count + 1;"
      , "      }"
      , "      count += 1;"
      , "    }"
      , "    if (end >= length) break;"
      , "    at = end + width;"
      , "  }"
      , "  return count;"
      , "}"
      , "/* The header pairs of a head every line of which the reader takes whole;"
      , "   an empty array asks the caller to read the head itself, which it does"
      , "   for a head with no header too. */"
      , "static pudu_box *pudu_http_header_pairs(pudu_text head, pudu_box *(*pair)(pudu_text, pudu_text)) {"
      , "  long count = pudu_http_header_lines(head, pair, NULL);"
      , "  pudu_box *pairs = pudu_array_new(count > 0 ? (size_t)count : 0);"
      , "  if (count > 0) (void)pudu_http_header_lines(head, pair, pairs->fields[0].items);"
      , "  return pairs;"
      , "}"
      ])
  ]
